<script>
const BASE=<?=json_encode(BASE_URL)?>,YEAR=<?=json_encode($year)?>,KEY='cdsCardDesignerV2Full';
const sample={name:'NGUYỄN VĂN AN',class_name:'10A1',code:'XM25010001',photo_url:'',verify_url:location.origin+BASE+'student_verify.php?id=sample&t=sample'};
const $=id=>document.getElementById(id),clone=o=>JSON.parse(JSON.stringify(o)),uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function textObj(id,label,text,x,y,w,h,font,color='#10243a',weight=700,align='center'){return{id,label,type:'text',text,x,y,w,h,font,color,weight,align,lineHeight:1.15,letter:0,italic:false,underline:false,nowrap:false,visible:true,locked:false}}
function defaults(type){const front=[{id:'logo',label:'Logo trường',type:'logo',src:'',x:4,y:4,w:12,h:12,fit:'contain',visible:true,locked:false},textObj('agency','Sở GD&ĐT','SỞ GD&ĐT TUYÊN QUANG',17,5,34,5,6,'#fff',700,'left'),textObj('school','Tên trường','TRƯỜNG PTDTNT THCS&THPT XÍN MẦN',17,10,34,7,7,'#fff',900,'left'),textObj('title','Tiêu đề','THẺ HỌC SINH',4,21,46,7,13,'#d71920',900),{id:'photo',label:'Ảnh học sinh',type:'photo',x:16,y:29,w:22,h:29.3,fit:'cover',visible:true,locked:false},textObj('name','Tên học sinh','{{student_name}}',4,60,46,7,9.5,'#1551a8',900),textObj('info','Lớp – Năm học','Lớp: {{class_name}}\nNăm học: {{school_year}}',6,67,42,9,7,'#10243a',700),textObj('code','Mã học sinh','Mã HS: {{student_code}}',6,77,42,5,6,'#10243a',700)];const back=[textObj('rulesTitle','Tiêu đề quy định','QUY ĐỊNH SỬ DỤNG THẺ',5,5,44,8,9,'#fff',900),textObj('rules','Nội quy','1. Thẻ học sinh là tài sản của nhà trường.\n2. Học sinh phải mang theo thẻ khi đến trường.\n3. Không cho người khác mượn thẻ.\n4. Không tẩy xóa, sửa chữa hoặc làm hư hỏng thẻ.\n5. Khi mất thẻ phải báo ngay cho nhà trường.',5,18,44,35,6.5,'#10243a',400,'left'),{id:'qr',label:'Mã QR',type:'qr',x:18,y:55,w:18,h:18,visible:true,locked:false},textObj('note','Ghi chú QR','Quét mã để xác minh học sinh hoặc sử dụng tại thư viện.',5,74,44,7,6,'#10243a',400)];if(type==='horizontal'){front.forEach(o=>{o.x*=1.55;o.y*=.62;o.w*=1.55;o.h*=.62});back.forEach(o=>{o.x*=1.55;o.y*=.62;o.w*=1.55;o.h*=.62})}return{type,face:'front',colors:{main:'#1551a8',second:'#45a5ef',accent:'#f6bd16'},front,back}}
let templates={vertical:defaults('vertical'),horizontal:defaults('horizontal')},state;try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s)templates={...templates,...s}}catch(e){}state=templates.vertical;let selected=null,grid=false,safe=true,history=[],future=[],students=[];
function dims(){return state.type==='vertical'?{w:54,h:86}:{w:90,h:60}}function objects(){return state[state.face]}function current(){return objects().find(o=>o.id===selected)}function push(){history.push(clone(templates));if(history.length>60)history.shift();future=[]}function persist(){localStorage.setItem(KEY,JSON.stringify(templates))}
function dataText(t,s){return String(t).replaceAll('{{student_name}}',s.name||'').replaceAll('{{class_name}}',s.class_name||'').replaceAll('{{school_year}}',YEAR).replaceAll('{{student_code}}',s.code||'')}
function objHtml(o,s,design){if(!o.visible)return'';let content='';if(o.type==='text')content=esc(dataText(o.text,s)).replace(/\n/g,'<br>');if(['logo','image'].includes(o.type))content=o.src?`<img src="${o.src}" style="object-fit:${o.fit||'contain'}">`:'<div class="w-100 h-100 d-flex align-items-center justify-content-center text-secondary border"><i class="bi bi-image"></i></div>';if(o.type==='photo')content=s.photo_url?`<img src="${esc(s.photo_url)}" style="object-fit:${o.fit||'cover'}">`:'<div class="w-100 h-100 d-flex align-items-center justify-content-center text-secondary border"><i class="bi bi-person fs-2"></i></div>';if(o.type==='qr')content='<div></div>';if(o.type==='shape')content='';if(o.type==='line')content='';const style=`left:${o.x}mm;top:${o.y}mm;width:${o.w}mm;height:${o.h}mm;${o.type==='text'?`font-size:${o.font}pt;color:${o.color};font-weight:${o.weight};font-style:${o.italic?'italic':'normal'};text-decoration:${o.underline?'underline':'none'};text-align:${o.align};line-height:${o.lineHeight};letter-spacing:${o.letter}px;white-space:${o.nowrap?'nowrap':'normal'};justify-content:${o.align==='left'?'flex-start':o.align==='right'?'flex-end':'center'};`:''}${o.type==='shape'?`background:${o.fill||'#cccccc'};border-radius:${o.radius||0}mm;`:''}${o.type==='line'?`background:${o.fill||'#10243a'};`:''}`;return `<div class="obj ${o.type} ${design&&o.id===selected?'selected':''} ${o.locked?'locked':''}" data-id="${o.id}" style="${style}">${content}${design?'<span class="handle"></span>':''}</div>`}
function faceHtml(face,s,design=false){return `<div class="card-face ${state.type} ${design?'design-face':''} ${grid&&design?'grid':''}"><div class="decor-top"></div><div class="decor-bottom"></div>${objectsFor(face).map(o=>objHtml(o,s,design&&face===state.face)).join('')}${safe&&design?'<div class="safe"></div>':''}</div>`}function objectsFor(f){return state[f]}
function qr(root,s){root.querySelectorAll('.obj.qr>div').forEach(el=>{el.innerHTML='';new QRCode(el,{text:s.verify_url||'',width:120,height:120,correctLevel:QRCode.CorrectLevel.M})})}
function render(){document.documentElement.style.setProperty('--main',state.colors.main);document.documentElement.style.setProperty('--second',state.colors.second);document.documentElement.style.setProperty('--accent',state.colors.accent);$('host').innerHTML=faceHtml(state.face,sample,true);qr($('host'),sample);bindObjects();renderLayers();renderProps();document.querySelectorAll('.type').forEach(b=>b.classList.toggle('active',b.dataset.type===state.type));document.querySelectorAll('.face').forEach(b=>b.classList.toggle('active',b.dataset.face===state.face));$('mainColor').value=state.colors.main;$('secondColor').value=state.colors.second;$('accentColor').value=state.colors.accent}
function bindObjects(){$('host').querySelectorAll('.obj').forEach(el=>{el.onpointerdown=startDrag;el.oncontextmenu=e=>{e.preventDefault();selected=el.dataset.id;render();showCtx(e.clientX,e.clientY)}})}
function startDrag(e){const o=objects().find(x=>x.id===e.currentTarget.dataset.id);selected=o.id;renderProps();renderLayers();if(o.locked)return;const el=$('host').querySelector(`[data-id="${o.id}"]`),face=el.parentElement,r=face.getBoundingClientRect(),d=dims(),sx=e.clientX,sy=e.clientY,ox=o.x,oy=o.y,isResize=e.target.classList.contains('handle'),ow=o.w,oh=o.h;push();el.setPointerCapture(e.pointerId);el.onpointermove=v=>{if(isResize){o.w=Math.max(1,Math.min(d.w-o.x,ow+(v.clientX-sx)/r.width*d.w));o.h=Math.max(.3,Math.min(d.h-o.y,oh+(v.clientY-sy)/r.height*d.h))}else{o.x=Math.max(0,Math.min(d.w-o.w,ox+(v.clientX-sx)/r.width*d.w));o.y=Math.max(0,Math.min(d.h-o.h,oy+(v.clientY-sy)/r.height*d.h))}render()};el.onpointerup=()=>{persist();render()}}
function renderLayers(){$('layers').innerHTML=[...objects()].reverse().map(o=>`<div class="layer ${o.id===selected?'active':''}" data-id="${o.id}"><button class="icon-btn eye" title="Ẩn/hiện"><i class="bi ${o.visible?'bi-eye':'bi-eye-slash'}"></i></button><span class="name">${esc(o.label)}</span><button class="icon-btn lock-mini"><i class="bi ${o.locked?'bi-lock-fill':'bi-unlock'}"></i></button><button class="icon-btn del-mini text-danger" title="Xóa"><i class="bi bi-trash"></i></button></div>`).join('');$('layers').querySelectorAll('.layer').forEach(el=>{el.onclick=e=>{selected=el.dataset.id;render()};el.oncontextmenu=e=>{e.preventDefault();selected=el.dataset.id;render();showCtx(e.clientX,e.clientY)}});$('layers').querySelectorAll('.eye').forEach(b=>b.onclick=e=>{e.stopPropagation();selected=b.closest('.layer').dataset.id;toggleVisible()});$('layers').querySelectorAll('.lock-mini').forEach(b=>b.onclick=e=>{e.stopPropagation();selected=b.closest('.layer').dataset.id;toggleLock()});$('layers').querySelectorAll('.del-mini').forEach(b=>b.onclick=e=>{e.stopPropagation();selected=b.closest('.layer').dataset.id;removeObj()})}
function renderProps(){const o=current();$('none').classList.toggle('hidden',!!o);$('form').classList.toggle('hidden',!o);if(!o)return;$('label').value=o.label;$('x').value=o.x.toFixed(1);$('y').value=o.y.toFixed(1);$('w').value=o.w.toFixed(1);$('h').value=o.h.toFixed(1);$('textBox').classList.toggle('hidden',o.type!=='text');$('assetBox').classList.toggle('hidden',!['logo','image'].includes(o.type));$('shapeBox').classList.toggle('hidden',!['shape','line'].includes(o.type));if(o.type==='text'){$('text').value=o.text;$('font').value=o.font;$('color').value=o.color;$('weight').value=o.weight;$('align').value=o.align;$('lineHeight').value=o.lineHeight;$('letter').value=o.letter;$('italic').checked=o.italic;$('underline').checked=o.underline;$('nowrap').checked=o.nowrap}if(['logo','image'].includes(o.type))$('fit').value=o.fit||'contain';if(['shape','line'].includes(o.type)){$('fill').value=o.fill||'#cccccc';$('radius').value=o.radius||0}$('lock').textContent=o.locked?'Mở khóa':'Khóa';$('visible').textContent=o.visible?'Ẩn':'Hiện'}
function update(){const o=current();if(!o)return;const d=dims();o.label=$('label').value;o.w=Math.max(1,Math.min(d.w,+$('w').value||1));o.h=Math.max(.3,Math.min(d.h,+$('h').value||.3));o.x=Math.max(0,Math.min(d.w-o.w,+$('x').value||0));o.y=Math.max(0,Math.min(d.h-o.h,+$('y').value||0));if(o.type==='text'){o.text=$('text').value;o.font=+$('font').value||8;o.color=$('color').value;o.weight=+$('weight').value;o.align=$('align').value;o.lineHeight=+$('lineHeight').value||1.15;o.letter=+$('letter').value||0;o.italic=$('italic').checked;o.underline=$('underline').checked;o.nowrap=$('nowrap').checked}if(['logo','image'].includes(o.type))o.fit=$('fit').value;if(['shape','line'].includes(o.type)){o.fill=$('fill').value;o.radius=+$('radius').value||0}persist();render()}
function add(type){push();const id=uid(),base={id,label:'Đối tượng mới',type,x:8,y:25,w:20,h:10,visible:true,locked:false};if(type==='text')Object.assign(base,{label:'Khối chữ mới',text:'Nội dung mới',font:9,color:'#10243a',weight:700,align:'center',lineHeight:1.15,letter:0,italic:false,underline:false,nowrap:false});if(type==='logo')Object.assign(base,{label:'Logo mới',src:'',w:15,h:15,fit:'contain'});if(type==='image')Object.assign(base,{label:'Ảnh mới',src:'',w:20,h:25,fit:'cover'});if(type==='qr')Object.assign(base,{label:'Mã QR',w:18,h:18});if(type==='shape')Object.assign(base,{label:'Hình màu',fill:'#dbeafe',radius:2,w:25,h:12});if(type==='line')Object.assign(base,{label:'Đường kẻ',fill:'#10243a',radius:0,w:30,h:.8});objects().push(base);selected=id;persist();render();if(['logo','image'].includes(type))chooseAsset()}
function removeObj(){const i=objects().findIndex(o=>o.id===selected);if(i<0)return;if(!confirm('Xóa đối tượng đang chọn?'))return;push();objects().splice(i,1);selected=null;persist();render()}function duplicateObj(){const o=current();if(!o)return;push();const n=clone(o);n.id=uid();n.label=o.label+' (bản sao)';n.x+=1;n.y+=1;objects().push(n);selected=n.id;persist();render()}function moveLayer(dir){const a=objects(),i=a.findIndex(o=>o.id===selected),j=i+dir;if(i<0||j<0||j>=a.length)return;push();[a[i],a[j]]=[a[j],a[i]];persist();render()}function toggleLock(){const o=current();if(!o)return;push();o.locked=!o.locked;persist();render()}function toggleVisible(){const o=current();if(!o)return;push();o.visible=!o.visible;persist();render()}
function chooseAsset(){const o=current();if(!o||!['logo','image'].includes(o.type))return;$('assetFile').value='';$('assetFile').click()}$('assetFile').onchange=e=>{const f=e.target.files?.[0],o=current();if(!f||!o)return;const r=new FileReader();r.onload=()=>{push();o.src=r.result;persist();render()};r.readAsDataURL(f)}
function showCtx(x,y){$('ctx').style.left=x+'px';$('ctx').style.top=y+'px';$('ctx').classList.remove('hidden')}document.addEventListener('click',e=>{if(!e.target.closest('#ctx'))$('ctx').classList.add('hidden')});$('ctx').onclick=e=>{const a=e.target.closest('button')?.dataset.a;if(!a)return;({duplicate:duplicateObj,up:()=>moveLayer(1),down:()=>moveLayer(-1),lock:toggleLock,visible:toggleVisible,delete:removeObj}[a])();$('ctx').classList.add('hidden')}
['label','x','y','w','h','text','font','color','weight','align','lineHeight','letter','italic','underline','nowrap','fit','fill','radius'].forEach(id=>$(id).addEventListener('input',update));document.querySelectorAll('.move').forEach(b=>b.onclick=()=>{const o=current();if(!o||o.locked)return;push();const d=dims(),s=+$('step').value;o.x=Math.max(0,Math.min(d.w-o.w,o.x+(+b.dataset.x)*s));o.y=Math.max(0,Math.min(d.h-o.h,o.y+(+b.dataset.y)*s));persist();render()});
$('addText').onclick=()=>add('text');$('addLogo').onclick=()=>add('logo');$('addImage').onclick=()=>add('image');$('addQr').onclick=()=>add('qr');$('addShape').onclick=()=>add('shape');$('addLine').onclick=()=>add('line');$('replaceAsset').onclick=chooseAsset;$('delete').onclick=removeObj;$('deleteTop').onclick=removeObj;$('duplicate').onclick=duplicateObj;$('duplicateTop').onclick=duplicateObj;$('up').onclick=()=>moveLayer(1);$('down').onclick=()=>moveLayer(-1);$('lock').onclick=toggleLock;$('visible').onclick=toggleVisible;$('centerH').onclick=()=>{const o=current();if(o){push();o.x=(dims().w-o.w)/2;persist();render()}};$('centerV').onclick=()=>{const o=current();if(o){push();o.y=(dims().h-o.h)/2;persist();render()}};$('gridBtn').onclick=()=>{grid=!grid;render()};$('safeBtn').onclick=()=>{safe=!safe;render()};
$('undo').onclick=()=>{if(!history.length)return;future.push(clone(templates));templates=history.pop();state=templates[state.type];selected=null;persist();render()};$('redo').onclick=()=>{if(!future.length)return;history.push(clone(templates));templates=future.pop();state=templates[state.type];selected=null;persist();render()};
document.querySelectorAll('.type').forEach(b=>b.onclick=()=>{state=templates[b.dataset.type];selected=null;render()});document.querySelectorAll('.face').forEach(b=>b.onclick=()=>{state.face=b.dataset.face;selected=null;render()});['mainColor','secondColor','accentColor'].forEach(id=>$(id).oninput=()=>{state.colors.main=$('mainColor').value;state.colors.second=$('secondColor').value;state.colors.accent=$('accentColor').value;persist();render()});$('save').onclick=()=>{persist();alert('Đã lưu mẫu Designer V2.')};$('reset').onclick=()=>{if(!confirm('Khôi phục toàn bộ mẫu mặc định?'))return;templates={vertical:defaults('vertical'),horizontal:defaults('horizontal')};state=templates.vertical;selected=null;persist();render()};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();removeObj()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateObj()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('undo').click()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();$('redo').click()}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&current()){e.preventDefault();const m={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key],s=+$('step').value*(e.shiftKey?5:1),o=current(),d=dims();push();o.x=Math.max(0,Math.min(d.w-o.w,o.x+m[0]*s));o.y=Math.max(0,Math.min(d.h-o.h,o.y+m[1]*s));persist();render()}});
function fullCard(s){return `<div class="fold">${faceHtml('front',s)}<div class="fold-line"></div>${faceHtml('back',s)}</div>`}function faceHtml(f,s){return `<div class="card-face ${state.type}"><div class="decor-top"></div><div class="decor-bottom"></div>${objectsFor(f).map(o=>objHtml(o,s,false)).join('')}</div>`}
$('studentsBtn').onclick=()=>{$('designer').classList.add('hidden');$('studentArea').classList.remove('hidden')};$('designBtn').onclick=()=>{$('studentArea').classList.add('hidden');$('designer').classList.remove('hidden')};$('grade').onchange=()=>{[...$('className').options].forEach((o,i)=>{if(i)o.hidden=!!$('grade').value&&o.dataset.grade!==$('grade').value});if($('className').selectedOptions[0]?.hidden)$('className').value=''};
async function loadStudents(){$('status').textContent='Đang tải...';const p=new URLSearchParams({grade:$('grade').value,class:$('className').value,q:$('search').value,photo:$('photo').value,limit:'1000'});try{const d=await fetch(BASE+'student_card_students.php?'+p,{credentials:'same-origin'}).then(r=>r.json());students=d.students||[];$('status').textContent='Đã tải '+students.length+' học sinh';$('results').innerHTML=students.map(s=>`<label class="student-row"><input class="form-check-input stu" type="checkbox" value="${esc(s.id)}"><img src="${esc(s.photo_url)}" onerror="this.style.visibility='hidden'"><span><b>${esc(s.name)}</b><small class="d-block text-muted">${esc(s.class_name)} · ${esc(s.code)}</small></span></label>`).join('')}catch(e){$('status').textContent='Lỗi tải dữ liệu'}}$('load').onclick=loadStudents;$('search').onkeydown=e=>{if(e.key==='Enter')loadStudents()};$('all').onclick=()=>{document.querySelectorAll('.stu').forEach(x=>x.checked=true);renderPrint()};$('clear').onclick=()=>{document.querySelectorAll('.stu').forEach(x=>x.checked=false);renderPrint()};$('results').onchange=renderPrint;
function renderPrint(){const ids=new Set([...document.querySelectorAll('.stu:checked')].map(x=>x.value)),rows=students.filter(s=>ids.has(String(s.id)));$('count').textContent=rows.length;$('printGrid').innerHTML=rows.map(fullCard).join('');rows.forEach((s,i)=>qr($('printGrid').children[i],s))}$('print').onclick=()=>{renderPrint();if(!$('printGrid').children.length)return alert('Hãy chọn học sinh.');setTimeout(()=>window.print(),100)};
render();
</script></body></html>